//! `mo clean`-style junk cleaning: scan well-known cache / log / trash locations,
//! show what each holds, delete the selected items.
//!
//! Everything listed here is regenerated by the owning app (caches, logs, build
//! caches) or is already in the Trash. App leftovers are listed for review and are
//! never pre-selected.

use super::{du, home, remove};
use rayon::prelude::*;
use std::collections::HashSet;
use std::path::{Path, PathBuf};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Group {
    Essentials,
    Browsers,
    Developer,
    Leftovers,
}

impl Group {
    pub const ALL: [Group; 4] = [Group::Essentials, Group::Browsers, Group::Developer, Group::Leftovers];
    pub fn label(self) -> &'static str {
        match self {
            Group::Essentials => "System junk",
            Group::Browsers => "Browsers",
            Group::Developer => "Developer tools",
            Group::Leftovers => "App leftovers",
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Mode {
    /// Delete everything inside the folder (keep the folder).
    Contents,
    /// Delete items inside the folder untouched for this many days.
    Older(u64),
    /// Delete the path itself.
    Whole,
}

#[derive(Clone, Debug)]
pub struct Item {
    pub path: String,
    pub bytes: u64,
    pub files: u64,
    pub on: bool,
}

#[derive(Clone, Debug)]
pub struct Category {
    pub id: &'static str,
    pub group: Group,
    pub icon: &'static str,
    pub title: &'static str,
    pub detail: &'static str,
    /// Pre-selected (regenerable).
    pub safe: bool,
    pub items: Vec<Item>,
}

impl Category {
    pub fn bytes(&self) -> u64 {
        self.items.iter().map(|i| i.bytes).sum()
    }
    pub fn selected_bytes(&self) -> u64 {
        self.items.iter().filter(|i| i.on).map(|i| i.bytes).sum()
    }
    pub fn selected(&self) -> usize {
        self.items.iter().filter(|i| i.on).count()
    }
}

struct Def {
    id: &'static str,
    group: Group,
    icon: &'static str,
    title: &'static str,
    detail: &'static str,
    safe: bool,
    targets: Vec<(PathBuf, Mode)>,
}

/// Cache folders that belong to the OS itself or that apps rebuild very slowly /
