/// Scan every category; empty ones are dropped.
pub fn scan() -> Vec<Category> {
    let defs = defs();
    let claimed: HashSet<PathBuf> = defs.iter().flat_map(|d| d.targets.iter().map(|(p, _)| p.clone())).collect();
    let mut cats: Vec<Category> = defs
        .par_iter()
        .map(|d| {
            let mut items: Vec<Item> = Vec::new();
            for (p, mode) in &d.targets {
                items.extend(list_target(p, *mode, &claimed, d.safe));
            }
            items.sort_by(|a, b| b.bytes.cmp(&a.bytes));
            Category { id: d.id, group: d.group, icon: d.icon, title: d.title, detail: d.detail, safe: d.safe, items }
        })
        .collect();
    #[cfg(target_os = "macos")]
    cats.push(leftovers());
    cats.retain(|c| c.bytes() > 0 || c.items.iter().any(|i| i.files > 0));
    cats
}

fn now() -> u64 {
    crate::index::now_secs()
}

fn list_target(p: &Path, mode: Mode, claimed: &HashSet<PathBuf>, on: bool) -> Vec<Item> {
    #[cfg(any(windows, all(unix, not(target_os = "macos"))))]
    if p.as_os_str() == "::recycle-bin" {
        return recycle_bin_item().into_iter().collect();
    }
    match mode {
        Mode::Whole => {
            if std::fs::symlink_metadata(p).is_err() {
                return Vec::new();
            }
            let (bytes, files) = du(p);
            vec![Item { path: p.to_string_lossy().into_owned(), bytes, files, on }]
        }
        Mode::Contents | Mode::Older(_) => {
            let Ok(rd) = std::fs::read_dir(p) else { return Vec::new() };
            let cutoff = match mode {
                Mode::Older(d) => Some(now().saturating_sub(d * 86_400)),
                _ => None,
            };
            let kids: Vec<PathBuf> = rd
                .flatten()
                .map(|e| e.path())
                .filter(|k| !claimed.contains(k))
                .filter(|k| {
                    let n = k.file_name().map(|s| s.to_string_lossy().to_ascii_lowercase()).unwrap_or_default();
                    !PROTECTED.iter().any(|x| n == *x) && n != ".ds_store" && n != ".localized"
                })
                .filter(|k| match cutoff {
                    Some(c) => {
                        let m = std::fs::symlink_metadata(k).ok().and_then(|m| m.modified().ok());
                        let secs = m.and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok()).map(|d| d.as_secs()).unwrap_or(u64::MAX);
                        secs < c
                    }
                    None => true,
                })
                .collect();
            kids.par_iter()
                .map(|k| {
                    let (bytes, files) = du(k);
                    Item { path: k.to_string_lossy().into_owned(), bytes, files, on }
                })
                .filter(|i| i.bytes > 0 || i.files > 0)
                .collect()
        }
    }
}

#[cfg(any(windows, all(unix, not(target_os = "macos"))))]
fn recycle_bin_item() -> Option<Item> {
    let items = trash::os_limited::list().ok()?;
    if items.is_empty() {
        return None;
    }
    let bytes: u64 = items.iter().filter_map(|i| trash::os_limited::metadata(i).ok()).filter_map(|m| m.size.size()).sum();
    Some(Item { path: "::recycle-bin".into(), bytes, files: items.len() as u64, on: true })
}

/// Result of a clean run.
#[derive(Clone, Debug, Default)]
pub struct CleanReport {
    pub freed: u64,
    pub removed: usize,
    pub failed: Vec<(String, String)>,
}

/// Delete all selected items. Items that partly fail are re-measured so the freed
/// figure stays honest.
pub fn clean(cats: &[Category]) -> CleanReport {
    let items: Vec<&Item> = cats.iter().flat_map(|c| c.items.iter()).filter(|i| i.on).collect();
    let results: Vec<(u64, Option<(String, String)>)> = items
        .par_iter()
        .map(|it| {
            #[cfg(any(windows, all(unix, not(target_os = "macos"))))]
            if it.path == "::recycle-bin" {
                return match trash::os_limited::list().and_then(trash::os_limited::purge_all) {
                    Ok(()) => (it.bytes, None),
                    Err(e) => (0, Some((it.path.clone(), e.to_string()))),
                };
            }
            let p = Path::new(&it.path);
            match remove(p) {
                Ok(()) => (it.bytes, None),
                Err(e) => {
                    let left = du(p).0;
                    (it.bytes.saturating_sub(left), Some((it.path.clone(), e.to_string())))
                }
            }
        })
        .collect();
    let mut r = CleanReport::default();
    for (freed, err) in results {
        r.freed += freed;
        match err {
            None => r.removed += 1,
            Some(e) => r.failed.push(e),
        }
    }
    r
}

/// macOS: support files whose bundle id belongs to no installed app.
#[cfg(target_os = "macos")]
fn leftovers() -> Category {
    let installed = super::apps::installed_bundle_ids();
    let vendors: HashSet<String> = installed.iter().filter_map(|id| vendor(id)).collect();
    let lib = home().join("Library");
    let dirs_ = ["Application Support", "Caches", "Preferences", "Saved Application State", "HTTPStorages", "WebKit", "Logs", "Cookies"];
    let mut cands: Vec<PathBuf> = Vec::new();
    for d in dirs_ {
        let Ok(rd) = std::fs::read_dir(lib.join(d)) else { continue };
        for e in rd.flatten() {
            let name = e.file_name().to_string_lossy().into_owned();
            let id = name.trim_end_matches(".plist").trim_end_matches(".savedState").trim_end_matches(".binarycookies").to_ascii_lowercase();
            if !looks_like_bundle_id(&id) || id.starts_with("com.apple.") || id.starts_with("group.") {
                continue;
            }
            if installed.contains(&id) || installed.iter().any(|i| id.starts_with(&format!("{i}.")) || i.starts_with(&format!("{id}."))) {
                continue;
            }
            if vendor(&id).is_some_and(|v| vendors.contains(&v)) {
                continue;
            }
            cands.push(e.path());
        }
    }
    let mut items: Vec<Item> = cands
        .par_iter()
        .map(|p| {
            let (bytes, files) = du(p);
            Item { path: p.to_string_lossy().into_owned(), bytes, files, on: false }
        })
        .filter(|i| i.bytes > 0)
        .collect();
    items.sort_by(|a, b| b.bytes.cmp(&a.bytes));
    Category {
        id: "leftovers",
        group: Group::Leftovers,
        icon: "🔧",
        title: "Leftovers of removed apps",
        detail: "Settings and support files whose app is no longer installed. Review before deleting.",
        safe: false,
        items,
    }
}

pub fn looks_like_bundle_id(s: &str) -> bool {
    let parts: Vec<&str> = s.split('.').collect();
    parts.len() >= 3
        && parts.iter().all(|p| !p.is_empty() && p.chars().all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_'))
        && parts[0].len() <= 5
}

/// "com.vendor.product" → "com.vendor".
pub fn vendor(id: &str) -> Option<String> {
    let mut it = id.split('.');
    let a = it.next()?;
    let b = it.next()?;
    it.next()?;
    Some(format!("{a}.{b}").to_ascii_lowercase())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bundle_ids() {
        assert!(looks_like_bundle_id("com.google.chrome"));
        assert!(looks_like_bundle_id("org.mozilla.firefox"));
        assert!(!looks_like_bundle_id("google"));
        assert!(!looks_like_bundle_id("Some App Support"));
        assert!(!looks_like_bundle_id("com.foo"));
        assert_eq!(vendor("com.google.Chrome.helper").as_deref(), Some("com.google"));
    }

    #[test]
    fn clean_contents_and_older() {
        let dir = std::env::temp_dir().join(format!("insight-clean-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("cache/a")).unwrap();
        std::fs::write(dir.join("cache/a/x.bin"), vec![1u8; 10_000]).unwrap();
        std::fs::write(dir.join("cache/y.bin"), vec![1u8; 5_000]).unwrap();
        let items = list_target(&dir.join("cache"), Mode::Contents, &HashSet::new(), true);
        assert_eq!(items.len(), 2);
        let older = list_target(&dir.join("cache"), Mode::Older(1), &HashSet::new(), true);
        assert!(older.is_empty(), "fresh files are not 'older than a day'");
        let cat = Category { id: "t", group: Group::Essentials, icon: "", title: "", detail: "", safe: true, items };
        let r = clean(&[cat]);
        assert_eq!(r.removed, 2);
        assert!(r.failed.is_empty());
        assert!(dir.join("cache").exists(), "the folder itself is kept");
        assert_eq!(std::fs::read_dir(dir.join("cache")).unwrap().count(), 0);
        let _ = std::fs::remove_dir_all(&dir);
    }
}
